            _Log($"USER_INPUT: parsed -> {FormatTerm(term)}");

            var activations = _userInput.Inject(term);
            _Log($"USER_INPUT: {activations.Count} activations");
            foreach (var goal in activations)
                _runtime.Gq.Enqueue(goal);

            await _RunUntilQuiescentAsync();
        }
        catch (Exception e)
        {
            // Dart two-binding `catch (e, st)` → `catch (Exception e)` + e.StackTrace.
            _Log($"USER_INPUT ERROR: {e.Message}\n{e.StackTrace}");
            _Output($"[ERROR] {e.Message}");
        }
    }

