    /// <summary>Handle incoming madGLP binary message.</summary>
    public async Task OnMadMessageReceivedAsync(string from, byte[] payload)
    {
        _Log($"MAD_RECV from {from} ({payload.Length} bytes)");

        if (_runtime == null || _ctx == null || _netInput == null)
        {
            _Log("MAD_RECV: ERROR - runtime/ctx/netInput is null");
            return;
        }

        // Local-capture for closure-narrowing through NRT (matches FlushMessages convention).
        var runtime = _runtime;
        var ctx = _ctx;
        var netInput = _netInput;

        var serializer = new PayloadSerializer(AgentId.ToLowerInvariant());
        var msg = serializer.DeserializeMessage(payload);
        _Log($"MAD_RECV: type={msg.Type}, dest={msg.Destination}");

        if (msg.Type == MessageType.Assignment)
        {
            try
            {
                // msg.Payload is List<byte>; DeserializeGlobalSendPayload takes byte[] — convert.
                var (globalName, value) = serializer.DeserializeGlobalSendPayload(
                    msg.Payload.ToArray(),
                    isReader =>
                    {
                        var (w, r) = runtime.Heap.AllocateVariable();
                        return isReader ? r : w;
                    });
                _Log($"MAD_ASSIGN: {globalName} := {FormatTerm(value)}");
                ctx.HandleMadAssignment(globalName, value, from.ToLowerInvariant());
                // Reactivation handled by BindVariable() inside MadContext.HandleMadAssignment
            }
            catch (Exception e)
            {
                _Log($"MAD_ERROR: {e.Message}");
            }
        }
        else if (msg.Type == MessageType.AgentMessage)
        {
            // msg.Payload is List<byte>; DeserializeAgentMessagePayload takes byte[] — convert.
            var term = serializer.DeserializeAgentMessagePayload(
                msg.Payload.ToArray(),
                isReader =>
                {
                    var (w, r) = runtime.Heap.AllocateVariable();
                    return isReader ? r : w;
                });
            var formatted = FormatTerm(term);
            _Log($"AGENT_MSG: {formatted}");

            _Log("INJECT into netInput");
            var activations = netInput.Inject(term);
            _Log($"INJECT: {activations.Count} activations");
            foreach (var goal in activations)
                runtime.Gq.Enqueue(goal);
        }
        else
        {
            _Log($"MAD_RECV: Unknown message type {msg.Type}");
        }

        UpdateStats();
        await _RunUntilQuiescentAsync();
    }

