    private async Task<string?> _RunUntilQuiescentAsync()
    {
        // async-without-internal-await: declared async for Dart shape fidelity (CS1998 acceptable).
        _Log($"RUN: start (GQ={_runtime?.Gq.Length ?? 0})");
        if (_scheduler == null || _runtime == null)
        {
            _Log("RUN: early return (not initialized)");
            return null;
        }

        try
        {
            // Per spec: drain all runnable goals, then flush outbound messages.
            var result = _scheduler.DrainWithStatus(debug: GlpTraceEnabled);
            _Log($"RUN: status={result.Status}, goals={result.GoalsRan.Count}");
            GoalCount += result.GoalsRan.Count;

            var messagesFlushed = _ctx!.FlushMessages();
            if (messagesFlushed > 0)
                _Log($"RUN: flushed {messagesFlushed} messages");

            UpdateStats();
            // Dart enum `.name` → C# `.ToString()` (default enum stringification returns member name).
            _Log($"RUN: done (status={result.Status})");
            return result.Status.ToString();
        }
        catch (Exception e)
        {
            _Log($"RUN ERROR: {e.Message}\n{e.StackTrace}");
            return "error";
        }
    }

