    public rt_Term ParseTerm(string termStr)
    {
        var parseInput = $"_temp_({termStr}).";
        var lexer = new Lexer(parseInput);
        var tokens = lexer.Tokenize();
        var parser = new Parser(tokens);
        var parsedAst = parser.Parse();

        if (parsedAst.Procedures.Count == 0 || parsedAst.Procedures[0].Clauses.Count == 0)
            throw new Exception("Could not parse term");

        var clause = parsedAst.Procedures[0].Clauses[0];
        if (clause.Head.Args.Count == 0)
            throw new Exception("No term to inject");

        return _AstToRuntimeTerm(clause.Head.Args[0]);
    }

    private rt_Term _AstToRuntimeTerm(ast_Term astTerm)
    {
        if (astTerm is ast_ConstTerm constTerm)
        {
            return new rt_ConstTerm(constTerm.Value);
        }
        else if (astTerm is ast_VarTerm varTerm)
        {
            var (writerAddr, readerAddr) = _runtime!.Heap.AllocateVariable();
            return new rt_VarRef(varTerm.IsReader ? readerAddr : writerAddr);
        }
        else if (astTerm is ast_StructTerm structTerm)
        {
            // Method-group conversion: LINQ Select with _AstToRuntimeTerm as method-group.
            var args = structTerm.Args.Select(_AstToRuntimeTerm).ToList();
            return new rt_StructTerm(structTerm.Functor, args);
        }
        else if (astTerm is ast_ListTerm listTerm)
        {
            return _AstListToRuntimeTerm(listTerm);
        }
        // Dart `runtimeType` → C# `GetType().Name` (unqualified type name).
        throw new Exception($"Unknown AST term type: {astTerm.GetType().Name}");
    }

    private rt_Term _AstListToRuntimeTerm(ast_ListTerm list)
    {
        if (list.IsNil)
            return new rt_ConstTerm("nil");

        var head = _AstToRuntimeTerm(list.Head!);

        rt_Term tail;
        // Dart nested ternary rewritten as if/else if/else for readability with is-pattern locals.
        if (list.Tail is ast_ListTerm tailList)
        {
            tail = _AstListToRuntimeTerm(tailList);
        }
        else if (list.Tail != null)
        {
            tail = _AstToRuntimeTerm(list.Tail);
        }
        else
        {
            tail = new rt_ConstTerm("nil");
        }

        // "." cons-cell functor and "nil" atom are LOAD-BEARING for heap recognition.
        return new rt_StructTerm(".", new List<rt_Term> { head, tail });
    }

    public rt_Term DerefTerm(rt_Term term)
    {
        if (_runtime == null) return term;

        if (term is rt_VarRef varRef)
        {
            var value = _runtime.Heap.GetValue(varRef.Addr);
            // C# 9+ negated pattern: `is not rt_VarRef` counterpart of Dart `is! rt.VarRef`.
            if (value != null && value is not rt_VarRef)
                return DerefTerm(value);
            return term;
        }
        if (term is rt_StructTerm structTerm)
        {
            var derefArgs = structTerm.Args.Select(DerefTerm).ToList();
            return new rt_StructTerm(structTerm.Functor, derefArgs);
        }
        return term;
    }

    public string FormatTerm(rt_Term term)
    {
        if (term is rt_ConstTerm constTerm)
        {
            object? val = constTerm.Value;
            if (val == null || (val is string s && s == "nil"))
                return "[]";
            return val.ToString() ?? "";
        }
        if (term is rt_VarRef varRef)
        {
            var isReader = _runtime?.Heap.IsReader(varRef.Addr) ?? false;
            return isReader ? $"X{varRef.Addr}?" : $"X{varRef.Addr}";
        }
        if (term is rt_StructTerm structTerm)
        {
            if (structTerm.Functor == "." && structTerm.Args.Count == 2)
            {
                var elements = new List<string>();
                rt_Term current = structTerm;
                // Pattern-in-while-condition (C# 8+) declares narrowed local per iteration.
                while (current is rt_StructTerm cs && cs.Functor == "." && cs.Args.Count == 2)
                {
                    elements.Add(FormatTerm(cs.Args[0]));
                    current = cs.Args[1];
                }
                if (current is rt_ConstTerm tail && (tail.Value == null || (tail.Value is string ts && ts == "nil")))
                    return $"[{string.Join(", ", elements)}]";
                return $"[{string.Join(", ", elements)} | {FormatTerm(current)}]";
            }
            var args = string.Join(", ", structTerm.Args.Select(FormatTerm));
            return $"{structTerm.Functor}({args})";
        }
        return term.ToString() ?? "";
    }

